<script setup lang="ts">
import { ref } from 'vue';
import { useSettings } from '@/composables/useSettings';
import { useToast } from '@/composables/useToast';
import { idToRaw } from '@/01-models/ids';
import type { ProviderProfileId } from '@/01-models/ids';
import type { ProviderProfile } from '@/01-models/types';
import { isHttpEndpoint } from '@/01-models/endpoint';
import {
  BookmarkPlusIcon, PencilIcon, TrashIcon, CheckIcon,
} from 'lucide-vue-next';
import { lazyStrings, ensureStrings } from '@/strings';
import { endpointTypeLabel } from './endpoint-type-label';

const props = defineProps<{
  profiles: ProviderProfile[],
}>();

const emit = defineEmits<{
  (e: 'update:profiles', value: ProviderProfile[]): void,
  (e: 'goToConnection'): void,
}>();

const { updateProviderProfiles } = useSettings();
const { addToast } = useToast();

// Profile Editing State
const editingProviderProfileId = ref<ProviderProfileId | null>(null);
const editingProviderProfileName = ref('');

async function handleDeleteProviderProfile({ id }: { id: ProviderProfileId }) {
  const index = props.profiles.findIndex(p => p.id === id);
  if (index === -1) return;

  const deletedProfile = props.profiles[index];
  if (!deletedProfile) return;

  const newProfiles = [...props.profiles];
  newProfiles.splice(index, 1);
  emit('update:profiles', newProfiles);
  await updateProviderProfiles({ profiles: JSON.parse(JSON.stringify(newProfiles)) });

  addToast({
    message: await ensureStrings.ProviderProfilesTab__profile_was_deleted({ profileName: deletedProfile.name }),
    actionLabel: await ensureStrings.ProviderProfilesTab__undo(),
    onAction: async () => {
      const restoredProfiles = [...newProfiles];
      restoredProfiles.splice(index, 0, deletedProfile);
      emit('update:profiles', restoredProfiles);
      await updateProviderProfiles({ profiles: JSON.parse(JSON.stringify(restoredProfiles)) });
    },
    duration: 5000,
  });
}

function startRename({ providerProfile }: { providerProfile: ProviderProfile }) {
  editingProviderProfileId.value = providerProfile.id;
  editingProviderProfileName.value = providerProfile.name;
}

async function saveRename() {
  if (!editingProviderProfileId.value) return;
  const index = props.profiles.findIndex(p => p.id === editingProviderProfileId.value);
  if (index !== -1 && editingProviderProfileName.value.trim()) {
    const newProfiles = JSON.parse(JSON.stringify(props.profiles)) as ProviderProfile[];
    const profile = newProfiles[index];
    if (profile) {
      profile.name = editingProviderProfileName.value.trim();
      emit('update:profiles', newProfiles);
      await updateProviderProfiles({ profiles: newProfiles });
    }
  }
  editingProviderProfileId.value = null;
}


defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/04b1edcb82c439719b61aa626f5ff993bf5802ec83cefddf02730ca5eccb027a.js";
import "virtual:naidan-tailwind-css-module/101edd00ea527063059f1fbba5b60f28c8ebde6b9eb15cfc63d6544cd4092d68.js";
import "virtual:naidan-tailwind-css-module/1467faa67f2e1854474547fd2dad2da1c52018e938e15e1166528fb49bfec94f.js";
import "virtual:naidan-tailwind-css-module/4a1930daeaefe9c8c797c5d90b38a8b4f804c2e1de40d06c67bc1bacf4169cf8.js";
import "virtual:naidan-tailwind-css-module/4a284388d0d5f15140334afecc655910c02414d2d6c5858c90a507a7def47b12.js";
import "virtual:naidan-tailwind-css-module/63dcd5d5283129e5fa0f51b7e4e92df326806d3caa3b006097625ff142db8cff.js";
import "virtual:naidan-tailwind-css-module/69d3f89da3142837a4bf41b7a4d41941850c442adf8f9f43ef7bb05b3728dd83.js";
import "virtual:naidan-tailwind-css-module/709ed96deaa339435123d358ec1c22eefdc0b28c1a00a5d90d3c3aa0e543334a.js";
import "virtual:naidan-tailwind-css-module/8fdd551b2cdeeacf2dcba337ea028124188e9718558419e3e2bb21a70813b340.js";
import "virtual:naidan-tailwind-css-module/bb93cf21b7cc6a8f8d90871881af790b8818a2cab885f7586a21e6c598d98c8f.js";
import "virtual:naidan-tailwind-css-module/bd5518240d103fdc790d66490d27072253d242a50b0873716ccac17cc344fd2b.js";
import "virtual:naidan-tailwind-css-module/e40bc904c786b5e9b6d5d61d2c4dd934a3c92e31e2662ea2701aeab4186f30e5.js";
