</script>

<template>
  <div data-testid="profiles-section" class="animate-in fade-in slide-in-from-bottom-2" tw-class="space-y-8 duration-400">
    <section tw-class="space-y-6">
      <div tw-class="flex items-center gap-2 pb-3 border-b border-gray-100 dark:border-gray-800">
        <BookmarkPlusIcon tw-class="w-5 h-5 text-blue-500" />
        <h2 tw-class="text-lg font-bold text-gray-800 dark:text-white tracking-tight">{{ lazyStrings.ProviderProfilesTab__provider_profiles() }}</h2>
      </div>

      <p tw-class="text-sm font-medium text-gray-500">{{ lazyStrings.ProviderProfilesTab__save_and_switch_provider_configurations() }}</p>

      <div v-if="!profiles || profiles.length === 0" tw-class="flex flex-col items-center justify-center p-16 bg-gray-50 dark:bg-gray-800/30 rounded-3xl border-2 border-dashed border-gray-200 dark:border-gray-800">
        <div tw-class="p-4 bg-white dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 mb-6">
          <BookmarkPlusIcon tw-class="w-12 h-12 text-gray-300" />
        </div>
        <p tw-class="text-sm text-gray-400 font-bold mb-6">{{ lazyStrings.ProviderProfilesTab__no_profiles_saved_yet() }}</p>
        <button
          @click="emit('goToConnection')"
          tw-class="px-8 py-3 bg-blue-600 text-white text-sm font-bold rounded-2xl hover:bg-blue-700 transition-all shadow-lg shadow-blue-500/20 active:scale-95"
        >
          {{ lazyStrings.ProviderProfilesTab__go_to_connection_to_create_one() }}
        </button>
      </div>

      <div v-else tw-class="grid grid-cols-1 gap-5">
        <div
          v-for="providerProfile in profiles"
          :key="idToRaw({ id: providerProfile.id })"
          tw-class="group p-6 bg-white dark:bg-gray-800/50 border border-gray-100 dark:border-gray-700 rounded-3xl flex items-center justify-between transition-all hover:border-blue-500/50 hover:shadow-xl hover:shadow-blue-500/5"
          data-testid="provider-profile-item"
        >
          <div tw-class="flex-1 min-w-0 mr-6">
            <div v-if="editingProviderProfileId === providerProfile.id" tw-class="flex items-center gap-2">
              <input
                v-model="editingProviderProfileName"
                @keydown.enter="$event => !$event.isComposing && saveRename()"
                @keyup.esc="editingProviderProfileId = null"
                tw-class="flex-1 bg-white dark:bg-gray-900 border-2 border-blue-500 rounded-xl px-4 py-2 text-sm font-bold text-gray-800 outline-none shadow-sm"
                autofocus
                data-testid="provider-profile-rename-input"
              />
              <button @click="saveRename" tw-class="p-2 text-green-600 hover:bg-green-50 dark:hover:bg-green-900/20 rounded-xl transition-colors"><CheckIcon tw-class="w-5 h-5" /></button>
            </div>
            <div v-else tw-class="flex items-center gap-4">
              <h3 tw-class="text-base font-bold text-gray-800 dark:text-white truncate">{{ providerProfile.name }}</h3>
              <span tw-class="text-[10px] px-2.5 py-1 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-lg font-bold uppercase tracking-wider border border-blue-100 dark:border-blue-900/30" data-testid="provider-type-badge">{{ endpointTypeLabel({ endpointType: providerProfile.endpoint.type }) }}</span>
            </div>
            <div tw-class="text-xs font-medium text-gray-400 mt-1.5 truncate">{{ isHttpEndpoint(providerProfile.endpoint) ? providerProfile.endpoint.url : '' }}</div>
            <div tw-class="text-[11px] font-bold text-gray-500 mt-2 flex items-center gap-3">
              <span tw-class="flex items-center gap-1.5 bg-gray-50 dark:bg-gray-800 px-2 py-0.5 rounded-lg border border-gray-100 dark:border-gray-700">{{ providerProfile.defaultModelId || lazyStrings.ProviderProfilesTab__no_default_model() }}</span>
              <span v-if="providerProfile.titleModelId" tw-class="text-[9px] opacity-60 px-2 py-0.5 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-transparent">{{ lazyStrings.ProviderProfilesTab__title_model({ modelId: providerProfile.titleModelId }) }}</span>
            </div>
          </div>

          <div tw-class="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all duration-200">
            <button
              @click="startRename({ providerProfile })"
              tw-class="p-2.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-xl transition-colors"
              :title="lazyStrings.ProviderProfilesTab__rename_profile()"
              data-testid="provider-profile-rename-button"
            >
              <PencilIcon tw-class="w-4 h-4" />
            </button>
            <button
              @click="handleDeleteProviderProfile({ id: providerProfile.id })"
              tw-class="p-2.5 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-xl transition-colors"
              :title="lazyStrings.ProviderProfilesTab__delete_profile()"
              data-testid="provider-profile-delete-button"
            >
              <TrashIcon tw-class="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </section>
  </div>
</template>
